DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_broker_operation'' OR command_type=''resolve_carousing_influence'' OR ')); END $$;
CREATE TABLE cmd_broker_operation_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,market_session_id bigint NOT NULL,operation_rule_id bigint NOT NULL,operation_code text NOT NULL,objective_reference text NOT NULL CHECK(btrim(objective_reference)<>''),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),campaign_day bigint NOT NULL,attempt_number_in_month smallint,trade_good_rule_id bigint REFERENCES rule_trade_good(trade_good_rule_id),price_percent smallint CHECK(price_percent>0),check_total smallint NOT NULL,effect smallint NOT NULL,succeeded boolean NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(market_session_id,campaign_id) REFERENCES mkt_session(market_session_id,campaign_id),FOREIGN KEY(operation_rule_id,operation_code) REFERENCES rule_broker_operation(rule_id,operation_code),CHECK((operation_code LIKE 'find-%')=(attempt_number_in_month IS NOT NULL)),CHECK((operation_code LIKE 'determine-%')=(trade_good_rule_id IS NOT NULL)),CHECK((price_percent IS NULL)=(operation_code LIKE 'find-%')));
CREATE TABLE cmd_carousing_influence_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,target_actor_id bigint NOT NULL,influence_command_id bigint NOT NULL UNIQUE REFERENCES enc_influence_attempt(command_id),skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),skill_modifier smallint NOT NULL,characteristic_modifier smallint NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(target_actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),CHECK(actor_id<>target_actor_id));
CREATE FUNCTION cmd_reject_broker_carousing_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Broker and Carousing receipts are immutable'; END $$;
CREATE TRIGGER cmd_broker_operation_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_broker_operation_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_broker_carousing_mutation();
CREATE TRIGGER cmd_carousing_influence_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_carousing_influence_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_broker_carousing_mutation();
